#include "metric_gather.h"
#include <iostream>
#include <iomanip>
using namespace aprl;using namespace source_coupling_math;
template<class F>long double smooth9(const EBCowanCoefficients& c,unsigned derivative,F f,unsigned a,long long i,long long j,long long k){
 const unsigned b=(derivative+1)%3,d=(derivative+2)%3;const long double delta=derivative==0?c.deltaYZ:(derivative==1?c.deltaZX:c.deltaXY);long double sum=c.alpha[derivative]*f(a,i,j,k);const long long q[3]={i,j,k};
 for(int s:{-1,1}){long long x[3]={q[0],q[1],q[2]},y[3]={q[0],q[1],q[2]};x[b]+=s;y[d]+=s;sum+=c.beta[b]*f(a,x[0],x[1],x[2]);sum+=c.beta[d]*f(a,y[0],y[1],y[2]);}for(int u:{-1,1})for(int v:{-1,1}){long long p[3]={i,j,k};p[b]+=u;p[d]+=v;sum+=delta*f(a,p[0],p[1],p[2]);}return sum;
}
void fill(EBFieldGrid& f,unsigned offset,bool previous){
 for(unsigned a=0;a<3;++a){auto& e=a==0?f.ex():(a==1?f.ey():f.ez());auto& b=a==0?f.bx():(a==1?f.by():f.bz());for(std::size_t k=0;k<e.nz();++k)for(std::size_t j=0;j<e.ny();++j)for(std::size_t i=0;i<e.nx();++i)e(i,j,k)=1e5*(previous?std::cos(.19*i+.23*j+.17*(k+offset)+a):std::sin(.31*i-.27*j+.21*(k+offset)+a));for(std::size_t k=0;k<b.nz();++k)for(std::size_t j=0;j<b.ny();++j)for(std::size_t i=0;i<b.nx();++i)b(i,j,k)=.003*(std::sin(.29*i+.17*j+.23*(k+offset)+a)+.3*std::cos(.11*i-.37*j+.13*(k+offset)));}
}
int main(int argc,char**argv){MPI_Init(&argc,&argv);int rank,size;MPI_Comm_rank(MPI_COMM_WORLD,&rank);MPI_Comm_size(MPI_COMM_WORLD,&size);const double dz=1.2543262415359034e-6;EBGridGeometry local(24,24,12,5e-6,5e-6,dz,dz/SI::c,EBMaxwellSolver::CowanZ),global=local;global.nz*=size;EBFieldGrid f(local),old(local),all(global),allOld(global);fill(f,rank*local.nz,false);fill(old,rank*local.nz,true);fill(all,0,false);fill(allOld,0,true);const auto saved=copyElectric(old);NativeHalo eh,oh,bh;eh.exchange(f,MPI_COMM_WORLD);oh.exchange(old,MPI_COMM_WORLD);bh.exchange(f,MPI_COMM_WORLD,true);const auto coefficients=f.cowanCoefficients();const Vec origin(0.);ChargeConservingCurrentDepositor dep(all,origin);long double maxWork=0.,maxMomentum=0.,oldWork=0.;
 const YeeComponent* ee[3]={&all.ex(),&all.ey(),&all.ez()},*eo[3]={&allOld.ex(),&allOld.ey(),&allOld.ez()},*bb[3]={&all.bx(),&all.by(),&all.bz()},*jj[3]={&all.jx(),&all.jy(),&all.jz()};auto rawE=[&](unsigned a,long long i,long long j,long long k){return .5L*((*ee[a])(i,j,k)+(long double)(*eo[a])(i,j,k));};auto rawB=[&](unsigned a,long long i,long long j,long long k){return (long double)(*bb[a])(i,j,k);};
 auto eMetric=[&](unsigned a,long long i,long long j,long long k){auto first=[&](unsigned b,long long x,long long y,long long z){return smooth9(coefficients,(a+1)%3,rawE,b,x,y,z);};return smooth9(coefficients,(a+2)%3,first,a,i,j,k);};auto bMetric=[&](unsigned a,long long i,long long j,long long k){return smooth9(coefficients,a,rawB,a,i,j,k);};
 for(unsigned seed=0;seed<96;++seed){Vec a(0.),b(0.);const double ds[3]={local.dx,local.dy,local.dz};for(unsigned c=0;c<3;++c){a[c]=(10.5+.19*std::cos(.7*seed+.8*c))*ds[c];b[c]=a[c]+.8*std::sin(.47*seed+.9*c)*ds[c];}a[2]=6.3*dz;b[2]=a[2]+.8*std::sin(.33*seed)*dz;
   if(seed%3==0&&rank>0){a[2]=.21*dz;b[2]=-.67*dz;}if(seed%3==1&&rank+1<size){a[2]=(local.nz-.21)*dz;b[2]=(local.nz+.67)*dz;}
   Vec ag(a),bg(b);ag[2]+=rank*local.nz*dz;bg[2]+=rank*local.nz*dz;all.clearCurrent();const Double charge=-SI::elementaryCharge;dep.depositSegment(ag,bg,charge);const auto E=matchedOpenOrbitElectric(f,&saved,origin,a,b,&eh,&oh);const auto B=matchedOrbitMagnetic(f,origin,a,b,&bh);const auto O=openOrbitElectric(f,&saved,origin,a,b,&eh,&oh);long double work=0.,momentum=0.,ws=0.,ps=0.;
   for(unsigned axis=0;axis<3;++axis){const auto& v=*jj[axis];for(std::size_t k=0;k<v.nz();++k)for(std::size_t j=0;j<v.ny();++j)for(std::size_t i=0;i<v.nx();++i)if(v(i,j,k)!=0.){const long double w=v(i,j,k)*eMetric(axis,i,j,k);work+=w;ws+=std::abs(w);if(axis<2){const unsigned m=1-axis;const long double p=(axis==0?1.L:-1.L)*v(i,j,k)*.5L*(bMetric(m,i,j,k-1)+bMetric(m,i,j,k));momentum+=p;ps+=std::abs(p);}}}
   const long double volume=(long double)local.dx*local.dy*local.dz*local.dt;work*=volume;momentum*=volume;ws*=volume;ps*=volume;const auto particleWork=chargeWork(charge,E,a,b);const long double particleP=(long double)charge*(((long double)b[0]-a[0])*B[1]-((long double)b[1]-a[1])*B[0]);maxWork=std::max(maxWork,std::abs(particleWork-work)/ws);oldWork=std::max(oldWork,std::abs(chargeWork(charge,O,a,b)-work)/ws);maxMomentum=std::max(maxMomentum,std::abs(particleP-momentum)/ps);
 }
 long double data[3]={maxWork,maxMomentum,oldWork},out[3]={};MPI_Allreduce(data,out,3,MPI_LONG_DOUBLE,MPI_MAX,MPI_COMM_WORLD);if(!(out[0]<5e-12&&out[1]<5e-12&&out[2]>1e-5)){if(!rank)std::cerr<<out[0]<<' '<<out[1]<<' '<<out[2]<<'\n';MPI_Abort(MPI_COMM_WORLD,1);}if(!rank)std::cout<<std::setprecision(18)<<"{\"ranks\":"<<size<<",\"orbits_per_rank\":96,\"weighted_work_relative_max\":"<<out[0]<<",\"weighted_magnetic_impulse_relative_max\":"<<out[1]<<",\"unweighted_negative_control_relative_max\":"<<out[2]<<"}\n";MPI_Finalize();
}
